const SITE_NAME = "DnD Miniatures STL";
const CONTACT = "info@dndminiaturestl.com"; // customer-facing (reply-to)
const OWNER = "seba.fyd@gmail.com"; // private sale notifications
const DEFAULT_FROM = SITE_NAME + ' <downloads@dndminiaturestl.com>';

function couponPercent(code) {
  try {
    const m = /^D20-(\d{1,2})-([A-Z0-9]{4})-([A-Fa-f0-9]{8})$/i.exec(String(code || '').trim());
    if (!m) return 0;
    const pct = parseInt(m[1], 10);
    if (!(pct >= 1 && pct <= 20)) return 0;
    const secret = process.env.COUPON_SECRET || process.env.PAYPAL_SECRET || 'd20-static';
    const sig = require('crypto').createHmac('sha256', secret).update('d20:' + pct + ':' + m[2].toUpperCase()).digest('hex').slice(0, 8);
    return sig === m[3].toLowerCase() ? pct : 0;
  } catch (e) { return 0; }
}

const LOGO_URL = "https://www.dndminiaturestl.com/images/logo.png";

async function paypalToken(base, id, secret) {
  const r = await fetch(base + '/v1/oauth2/token', {
    method: 'POST',
    headers: {
      Authorization: 'Basic ' + Buffer.from(id + ':' + secret).toString('base64'),
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: 'grant_type=client_credentials',
  });
  if (!r.ok) return null;
  const j = await r.json();
  return j.access_token || null;
}

// Best-effort delivery-failure log (Redis list dnd:deliver-errors, newest first).
// Every buyer who pays but gets no links/email lands here — check it whenever a
// "did not receive item" complaint or PayPal dispute shows up.
async function logDeliverError(stage, data) {
  try {
    const rUrl = process.env.UPSTASH_REDIS_REST_URL || process.env.KV_REST_API_URL;
    const rTok = process.env.UPSTASH_REDIS_REST_TOKEN || process.env.KV_REST_API_TOKEN;
    if (!rUrl || !rTok) return;
    await fetch(rUrl + '/pipeline', {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + rTok, 'Content-Type': 'application/json' },
      body: JSON.stringify([
        ['LPUSH', 'dnd:deliver-errors', JSON.stringify(Object.assign({ t: Date.now(), stage: stage }, data || {}))],
        ['LTRIM', 'dnd:deliver-errors', 0, 499],
      ]),
    });
  } catch (e) { /* ignore */ }
}

module.exports = async function handler(req, res) {
  res.setHeader('Cache-Control', 'no-store');
  if (req.method !== 'POST') { res.status(405).json({ error: 'method_not_allowed' }); return; }
  try {
    const body = (req.body && typeof req.body === 'object') ? req.body : JSON.parse(req.body || '{}');
    const orderID = body.orderID;
    if (!orderID || typeof orderID !== 'string' || orderID.length > 64) { res.status(400).json({ error: 'bad_order_id' }); return; }

    const id = process.env.PAYPAL_CLIENT_ID;
    const secret = process.env.PAYPAL_SECRET;
    if (!id || !secret) { await logDeliverError('not_configured', { order: orderID }); res.status(500).json({ error: 'not_configured' }); return; }

    const bases = process.env.PAYPAL_API_BASE
      ? [process.env.PAYPAL_API_BASE]
      : ['https://api-m.paypal.com', 'https://api-m.sandbox.paypal.com'];
    let order = null;
    for (const base of bases) {
      const token = await paypalToken(base, id, secret);
      if (!token) continue;
      const r = await fetch(base + '/v2/checkout/orders/' + encodeURIComponent(orderID), {
        headers: { Authorization: 'Bearer ' + token },
      });
      if (r.ok) { order = await r.json(); break; }
    }
    if (!order) { await logDeliverError('order_not_found', { order: orderID }); res.status(404).json({ error: 'order_not_found' }); return; }
    if (order.status !== 'COMPLETED') { await logDeliverError('not_completed', { order: orderID, status: order.status }); res.status(402).json({ error: 'not_completed' }); return; }

    const unit = (order.purchase_units || [])[0] || {};
    const slug = unit.custom_id;

    let product = null;
    if (slug && slug.indexOf('CART') === 0) {
      const parts = slug.split('|');
      const coupon = (parts[1] || '').trim();
      // Slug sources, most to least trusted. PayPal drops purchase_units[].items from
      // GET /v2/checkout/orders after capture on some order types, so items alone is not
      // enough — fall back to the slug list baked into custom_id at order creation, then
      // to the slugs the client POSTed. All sources are validated against CATALOG and the
      // captured amount must still cover the resolved cart, so none of them can over-deliver.
      const slugSources = [];
      slugSources.push((unit.items || []).map(it => String(it.sku || '').trim()));
      slugSources.push(String(parts.slice(2).join('|') || '').split(',').map(s => s.trim()));
      slugSources.push(Array.isArray(body.slugs) ? body.slugs.slice(0, 40).map(s => String(s || '').trim()) : []);
      // custom_id is capped at 127 chars so its slug list can arrive truncated — keep the
      // source that resolves the most catalog slugs instead of the first non-empty one.
      let slugsInCart = [];
      for (const source of slugSources) {
        const valid = [];
        for (const s of source) if (CATALOG[s] && valid.indexOf(s) === -1) valid.push(s);
        if (valid.length > slugsInCart.length) slugsInCart = valid;
      }
      if (slugsInCart.length) {
        const cartSubtotal = slugsInCart.reduce((t, s) => t + CATALOG[s].price, 0);
        const pct = couponPercent(coupon);
        const required = Math.round(cartSubtotal * (100 - pct)) / 100;
        const allLinks = [];
        for (const s of slugsInCart) for (const l of CATALOG[s].links) allLinks.push(l);
        product = {
          title: slugsInCart.map(s => CATALOG[s].title.split(' STL')[0]).join(', ').slice(0, 110) + ' (' + slugsInCart.length + (slugsInCart.length > 1 ? ' items' : ' item') + ')',
          price: required,
          links: allLinks,
        };
      }
    } else {
      product = slug && CATALOG[slug];
    }

    if (!product) { await logDeliverError('unknown_product', { order: orderID, custom_id: slug || null, items: (unit.items || []).map(i => i.sku), bodySlugs: Array.isArray(body.slugs) ? body.slugs : null }); res.status(404).json({ error: 'unknown_product' }); return; }

    const cap = (((unit.payments || {}).captures) || [])[0] || {};
    const paid = parseFloat(((cap.amount || {}).value) || ((unit.amount || {}).value) || '0');
    if (!(paid + 0.001 >= product.price)) { await logDeliverError('amount_mismatch', { order: orderID, custom_id: slug || null, paid: paid, required: product.price }); res.status(402).json({ error: 'amount_mismatch' }); return; }

    const prefEmail = (typeof body.email === 'string' && body.email.trim().length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(body.email.trim()))
      ? body.email.trim().toLowerCase() : null;
    const buyerEmail = prefEmail || (order.payer || {}).email_address || null;
    let emailSent = false;
    const key = process.env.RESEND_API_KEY;
    if (key && buyerEmail) {
      const linksHtml = product.links.map(function (l) {
        var thumb = l.img ? '<img src="' + l.img + '" width="88" height="88" alt="' + l.name + '" style="display:block;border-radius:10px;object-fit:cover">' : '';
        return '<table cellpadding="0" cellspacing="0" style="margin:12px 0;width:100%"><tr>'
          + '<td style="width:100px;vertical-align:middle">' + thumb + '</td>'
          + '<td style="padding-left:14px;vertical-align:middle"><a href="' + l.url + '" style="color:#1a7f4e;font-weight:bold;font-size:15px">&#11015; ' + l.name + ' (.STL)</a></td>'
          + '</tr></table>';
      }).join('');
      const html = '<div style="font-family:Arial,sans-serif;max-width:560px;margin:0 auto;color:#222">'
        + '<img src="' + LOGO_URL + '" alt="' + SITE_NAME + '" width="200" style="display:block;margin:0 0 10px">'
        + '<p>Thank you for your purchase! Here ' + (product.links.length > 1 ? 'are your download links' : 'is your download link') + ' for <b>' + product.title + '</b>:</p>'
        + linksHtml
        + '<p style="font-size:13px;color:#666">License: personal use + selling physical prints is OK. Redistributing the digital files is not.</p>'
        + '<p style="font-size:13px;color:#666">Questions or print help: just reply to this email.</p>'
        + '<div style="background:#f7f4ec;border:1px solid #e0d8c4;border-radius:10px;padding:14px 16px;margin-top:20px">'
        + '<p style="margin:0;font-size:13px;color:#555"><b>Printed it? We would love to see.</b> Reply with a photo of your print and a line or two — real reviews from real adventurers go on the site, and as a thank-you we send you a <b>10% off code</b> for your next order.</p>'
        + '</div>'
        + '</div>';
      try {
        const mr = await fetch('https://api.resend.com/emails', {
          method: 'POST',
          headers: { Authorization: 'Bearer ' + key, 'Content-Type': 'application/json' },
          body: JSON.stringify({
            from: process.env.RESEND_FROM || DEFAULT_FROM,
            to: [buyerEmail],
            bcc: [OWNER],
            reply_to: CONTACT,
            subject: 'Your ' + product.title.split(' STL')[0] + ' STL — download links',
            html: html,
          }),
        });
        emailSent = mr.ok;
        if (!mr.ok) {
          let detail = '';
          try { detail = (await mr.text()).slice(0, 300); } catch (e2) { /* ignore */ }
          await logDeliverError('resend_failed', { order: orderID, to: buyerEmail, status: mr.status, detail: detail });
        }
      } catch (e) {
        emailSent = false;
        await logDeliverError('resend_exception', { order: orderID, to: buyerEmail, message: String(e && e.message || e).slice(0, 200) });
      }
    }
    if (!key) await logDeliverError('resend_key_missing', { order: orderID, to: buyerEmail });

    // Log sale to Redis for /oculto metrics — best-effort, deduped by order ID
    const rUrl = process.env.UPSTASH_REDIS_REST_URL || process.env.KV_REST_API_URL;
    const rTok = process.env.UPSTASH_REDIS_REST_TOKEN || process.env.KV_REST_API_TOKEN;
    if (rUrl && rTok) {
      try {
        const rh = { Authorization: 'Bearer ' + rTok, 'Content-Type': 'application/json' };
        const first = await fetch(rUrl + '/pipeline', { method: 'POST', headers: rh, body: JSON.stringify([['SET', 'dnd:o:' + orderID, '1', 'NX', 'EX', 7776000]]) });
        const fj = first.ok ? await first.json() : null;
        if (fj && fj[0] && fj[0].result === 'OK') {
          await fetch(rUrl + '/pipeline', { method: 'POST', headers: rh, body: JSON.stringify([
            ['LPUSH', 'dnd:sales', JSON.stringify({ t: Date.now(), slug: slug, title: product.title, paid: paid, buyer: buyerEmail, order: orderID })],
            ['LTRIM', 'dnd:sales', 0, 999],
          ]) });
        }
      } catch (e) { /* ignore */ }
    }

    // Sale notification to shop owner — best-effort, never blocks delivery
    if (key) {
      try {
        await fetch('https://api.resend.com/emails', {
          method: 'POST',
          headers: { Authorization: 'Bearer ' + key, 'Content-Type': 'application/json' },
          body: JSON.stringify({
            from: process.env.RESEND_FROM || DEFAULT_FROM,
            to: [OWNER],
            subject: '[Sale] ' + SITE_NAME + ': ' + product.title.split(' STL')[0] + ' — $' + paid.toFixed(2),
            html: '<div style="font-family:Arial,sans-serif;max-width:560px;color:#222">'
              + '<h2 style="margin:0 0 12px">New sale on ' + SITE_NAME + ' &#127881;</h2>'
              + '<p><b>Product:</b> ' + product.title + '</p>'
              + '<p><b>Amount:</b> $' + paid.toFixed(2) + ' USD</p>'
              + '<p><b>Buyer:</b> ' + (buyerEmail || 'unknown') + '</p>'
              + '<p><b>PayPal Order ID:</b> ' + orderID + '</p>'
              + '<p><b>Delivery email to buyer:</b> ' + (emailSent ? 'sent OK' : 'NOT SENT — send the links manually') + '</p>'
              + '</div>',
          }),
        });
      } catch (e) { /* ignore */ }
    }

    // Omnisend "placed order" event — best-effort, never blocks delivery
    try {
      const omniKey = process.env.OMNISEND_API_KEY;
      if (omniKey && buyerEmail) {
        await fetch('https://api.omnisend.com/api/events', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', Authorization: omniKey, 'Omnisend-Version': '2026-03-15' },
          body: JSON.stringify({
            eventName: 'placed order',
            origin: 'api',
            eventVersion: 'v2',
            eventTime: new Date().toISOString(),
            contact: { email: buyerEmail },
            properties: {
              orderID: orderID,
              orderNumber: orderID,
              currency: 'USD',
              createdAt: new Date().toISOString(),
              totalPrice: paid,
              subTotalPrice: paid,
              paymentStatus: 'paid',
              fulfillmentStatus: 'fulfilled',
              lineItems: [{ productID: slug, productTitle: product.title, productPrice: product.price, productQuantity: 1 }],
            },
          }),
        });
      }
    } catch (e) { /* ignore */ }

    res.status(200).json({ ok: true, links: product.links, emailSent: emailSent, buyerEmail: buyerEmail });
  } catch (e) {
    try { await logDeliverError('exception', { message: String(e && e.message || e).slice(0, 300) }); } catch (e2) { /* ignore */ }
    res.status(500).json({ error: 'delivery_failed' });
  }
};
